return ['domain'=>'woolab-ic-dic','plural-forms'=>'nplurals=3; plural=(n==1 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'pl_PL','project-id-version'=>'Kybernaut IC DIC 2.0.0','pot-creation-date'=>'2026-10-25T18:01:39+00:00','po-revision-date'=>'2026-10-25T21:38:13+00:00','x-generator'=>'WP-CLI 2.12.0','messages'=>['Adds Czech Company & VAT numbers (IČO & DIČ) to WooCommerce billing fields and verifies if data are correct.'=>'Dodaje do pól rozliczeniowych WooCommerce czeski numer identyfikacyjny firmy i numer VAT (IČO i DIČ) oraz sprawdza ich poprawność.','View GitHub'=>'Zobacz na GitHubie','GitHub'=>'GitHub','Write a Review'=>'Napisz recenzję','View Kybernaut IČO DIČ settings'=>'Zobacz ustawienia Kybernaut IČO DIČ','Settings'=>'Ustawienia','Business ID is invalid.'=>'Numer identyfikacyjny firmy jest nieprawidłowy.','Unexpected error occurred. Try it again.'=>'Wystąpił nieoczekiwany błąd. Spróbuj ponownie.','Clear company details'=>'Wyczyść dane firmy','Validating data in ARES.'=>'Trwa weryfikacja danych w ARES.','Information loaded succesfully from ARES.'=>'Dane zostały wczytane z ARES.','Validating data in Finančná správa.'=>'Trwa weryfikacja danych w Finančná správa.','Information loaded succesfully from Finančná správa.'=>'Dane zostały wczytane z Finančná správa.','Validating data in %s.'=>'Trwa weryfikacja danych w rejestrze %s.','Information loaded successfully from %s.'=>'Dane zostały wczytane z rejestru %s.','Turn on "%s" first.'=>'Najpierw włącz „%s”.','CZ: Validate Business ID in ARES'=>'CZ: Weryfikuj IČO w ARES','SK: Validate in Finančná správa'=>'SK: Weryfikuj w Finančná správa','Turn on at least one of the ARES, Finančná správa or VIES checks first.'=>'Najpierw włącz co najmniej jedną z weryfikacji: ARES, Finančná správa lub VIES.','Buying as a company'=>'Faktura na firmę','Reverse charge: the order is without VAT, the buyer accounts for it.'=>'Odwrotne obciążenie: zamówienie nie zawiera VAT, podatek rozlicza nabywca.','This tax number is valid. Without the country code (%s) it is not an EU VAT ID, so the order is placed with VAT.'=>'Ten numer podatkowy jest prawidłowy. Bez kodu kraju (%s) nie jest to numer NIP-UE, dlatego zamówienie będzie zawierać VAT.','This %s is not registered for VAT in the EU (VIES), so the order is placed with VAT.'=>'Numer z pola %s nie jest zarejestrowany do celów VAT w UE (VIES), dlatego zamówienie będzie zawierać VAT.','Business ID'=>'Numer identyfikacyjny firmy','Tax ID'=>'NIP','VAT reg. no.'=>'NIP-UE','Czech DIČ fieldVAT ID'=>'NIP-UE','EU VAT number fieldVAT ID'=>'NIP-UE','Slovak IČ DPH fieldVAT ID'=>'NIP-UE','optional, only if you are a VAT payer'=>'opcjonalnie, tylko jeśli jesteś czynnym podatnikiem VAT','label before a value%s: '=>'%s: ','Verification of VAT number has failed.'=>'Weryfikacja numeru NIP-UE nie powiodła się.','Caution!'=>'Uwaga!','Please, make sure the VAT number is valid before processing the order.'=>'Przed realizacją zamówienia upewnij się, że numer NIP-UE jest prawidłowy.','Business ID not set.'=>'Nie podano numeru identyfikacyjnego firmy.','Business ID must be a number and 8 digits long.'=>'Numer identyfikacyjny firmy musi składać się z 8 cyfr.','An error occured while connecting to ARES, try it again later.'=>'Wystąpił błąd podczas łączenia z rejestrem ARES. Spróbuj ponownie później.','Entity doesn\'t exist in ARES.'=>'Podmiot nie istnieje w rejestrze ARES.','ARES is not responding.'=>'Rejestr ARES nie odpowiada.','Finančná správa lists are not available.'=>'Listy Finančná správa nie są dostępne.','Business ID not found in Finančná správa, fill in the details manually.'=>'Nie znaleziono numeru identyfikacyjnego firmy w bazie Finančná správa. Uzupełnij dane ręcznie.','Kybernaut IČO DIČ: the Finančná správa DIČ / IČ DPH lists are missing or older than a week, so those numbers cannot be validated. The import runs daily through WP-Cron (or run "wp woolab-icdic sk-import"); failures are logged in WooCommerce → Status → Logs.'=>'Kybernaut IČO DIČ: listy DIČ / IČ DPH z Finančná správa nie zostały zaimportowane lub są starsze niż tydzień, więc tych numerów nie można zweryfikować. Import uruchamia się codziennie przez WP-Cron (możesz też uruchomić „wp woolab-icdic sk-import”); błędy są zapisywane w WooCommerce → Status → Dziennik zdarzeń.','Kybernaut IČO DIČ: the Finančná správa DIČ / IČ DPH lists cannot be imported, the zip, xmlreader and pdo_sqlite PHP extensions are required (ask your hosting).'=>'Kybernaut IČO DIČ: nie można zaimportować list DIČ / IČ DPH z Finančná správa, ponieważ brakuje rozszerzeń PHP zip, xmlreader i pdo_sqlite (zapytaj dostawcę hostingu).','Import status'=>'Stan importu','This feature is not compatible with Fluid Checkout for WooCommerce.'=>'Ta funkcja nie jest zgodna z wtyczką Fluid Checkout for WooCommerce.','Kybernaut IČO DIČ options'=>'Opcje Kybernaut IČO DIČ','The following options affect how Business ID and VAT number behaves.'=>'Poniższe opcje określają działanie pól numeru identyfikacyjnego firmy i numeru NIP-UE.','Toggle fields visibility'=>'Przełącznik widoczności pól','Enable toggle switch to show/hide input fields'=>'Włącz przełącznik do pokazywania i ukrywania pól','Move Country to top'=>'Przenieś pole Kraj na górę','Move Country field above the "Buying as a company" toggle'=>'Przenieś pole Kraj nad przełącznik „Faktura na firmę”','Company fields'=>'Pola firmy','The company name and the Business ID (in the Czech Republic and Slovakia, where every company has one). "Required for companies" works best with the toggle: without it, a filled-in company name makes the customer a company. The DIČ of the shop\'s own country follows it only with "Require DIČ". The VAT ID stays optional, abroad with "only if you are a VAT payer".'=>'Nazwa firmy i numer identyfikacyjny firmy (w Czechach i na Słowacji, gdzie ma go każda firma). Opcja „Wymagane dla firm” działa najlepiej z przełącznikiem: bez niego klient, który wpisze nazwę firmy, jest traktowany jak firma. DIČ kraju sklepu podlega tej opcji tylko po włączeniu „Wymagaj DIČ”. NIP-UE pozostaje opcjonalny, a klienci z innych krajów widzą przy nim dopisek „tylko jeśli jesteś czynnym podatnikiem VAT”.','Optional: "(optional)", as WooCommerce marks fields'=>'Opcjonalne: „(opcjonalnie)”, tak jak WooCommerce oznacza pola','No mark: like any other field'=>'Bez oznaczenia: jak każde inne pole','Asterisk: marked required, the order goes through without them'=>'Gwiazdka: oznaczone jako wymagane, ale zamówienie można złożyć bez nich','Required for companies: no order without them (recommended)'=>'Wymagane dla firm: bez nich nie można złożyć zamówienia (zalecane)','Require DIČ'=>'Wymagaj DIČ','A company from the shop\'s own country that enters its IČO has to enter its DIČ too, and "Required for companies" asks for it. Off by default: non-profit organizations may have an IČO but no DIČ.'=>'Firma z kraju sklepu, która poda IČO, musi podać również DIČ; w trybie „Wymagane dla firm” DIČ jest wymagany zawsze. Domyślnie wyłączone: organizacje non-profit mogą mieć IČO bez DIČ.','Enable validation of VAT number in EU database VIES.'=>'Włącz weryfikację numeru NIP-UE w unijnej bazie VIES.','Enable VAT exemption for valid EU VAT numbers'=>'Włącz zwolnienie z VAT dla prawidłowych numerów NIP-UE','To enable this feature, turn on taxes in your store.'=>'Aby włączyć tę funkcję, włącz podatki w sklepie.','To enable this feature, set your base country to one of the EU VAT countries.'=>'Aby włączyć tę funkcję, ustaw jako kraj sklepu jeden z krajów UE objętych VAT.','Check Business ID, DIČ and IČ DPH in the Finančná správa lists, downloaded daily (about 70 MB) into a SQLite file in the uploads folder (about 190 MB). Business IDs not in the lists yet (new, or not registered for tax) are accepted without autofill. IČ DPH is checked in VIES only when the lists do not have it.'=>'Sprawdzaj IČO, DIČ i IČ DPH na listach Finančná správa, pobieranych codziennie (ok. 70 MB) do pliku SQLite w katalogu uploads (ok. 190 MB). IČO, których jeszcze nie ma na listach (nowe lub niezarejestrowane do celów podatkowych), są akceptowane bez autouzupełniania. IČ DPH jest sprawdzany w VIES tylko wtedy, gdy nie ma go na listach.','Czech Republic'=>'Czechy','Enable validation of Business ID in Czech database ARES.'=>'Włącz weryfikację IČO w czeskiej bazie ARES.','CZ: Validate and autofill based on ARES'=>'CZ: Weryfikuj i uzupełniaj dane z ARES','Enable company name search, and autofill and validation for Company, VAT number, Address, City, and Postcode fields based on Czech database ARES. Requires checked the option above.'=>'Włącz wyszukiwanie po nazwie firmy oraz autouzupełnianie i weryfikację pól Firma, NIP-UE, Adres, Miasto i Kod pocztowy na podstawie czeskiej bazy ARES. Wymaga zaznaczenia opcji powyżej.','Slovakia'=>'Słowacja','SK: Validate and autofill based on Finančná správa'=>'SK: Weryfikuj i uzupełniaj dane z Finančná správa','Enable company name search, and autofill and validation for Company, DIČ, IČ DPH, Address, City, and Postcode fields. Requires checked the option above.'=>'Włącz wyszukiwanie po nazwie firmy oraz autouzupełnianie i weryfikację pól Firma, NIP (DIČ), NIP-UE (IČ DPH), Adres, Miasto i Kod pocztowy. Wymaga zaznaczenia opcji powyżej.','SK: Disable DIČ / IČ DPH match check'=>'SK: Wyłącz sprawdzanie zgodności DIČ / IČ DPH','Disable validation that IČ DPH must equal "SK" + DIČ. Some non-profit organizations have IČ DPH that does not match their DIČ.'=>'Wyłącz sprawdzanie, czy IČ DPH jest równy „SK” + DIČ. Niektóre organizacje non-profit mają IČ DPH, który nie odpowiada ich DIČ.','European Union'=>'Unia Europejska','EU: Validate VAT number in VIES'=>'UE: Weryfikuj NIP-UE w VIES','Business ID only where companies have one'=>'Numer identyfikacyjny firmy (IČO) tylko tam, gdzie istnieje','Hide the Business ID field for billing countries other than Slovakia and the Czech Republic, whose companies have no IČO. The list can be changed with the woolab_icdic_ic_countries filter.'=>'Ukryj pole numeru identyfikacyjnego firmy w krajach rozliczeniowych, w których firmy nie mają IČO (wszystkich poza Czechami i Słowacją). Listę krajów można zmienić filtrem woolab_icdic_ic_countries.','EU: VAT exempt'=>'UE: Zwolnienie z VAT','When a check fails'=>'Gdy weryfikacja się nie powiedzie','Ignore when ARES, Finančná správa or VIES check fails for technical reasons'=>'Ignoruj nieudaną weryfikację w ARES, Finančná správa lub VIES z przyczyn technicznych','Allow the creation of an order if the verification of the Business ID in ARES or Finančná správa, or the VAT number in the European VIES database fails for technical reasons.'=>'Pozwól złożyć zamówienie, jeśli weryfikacja IČO w ARES lub Finančná správa albo numeru NIP-UE w unijnej bazie VIES nie powiedzie się z przyczyn technicznych.','Leave empty to follow the theme.'=>'Pozostaw puste, aby użyć kolorów motywu.','Status icons'=>'Ikony stanu','The padlock on the company name and Business ID after an autofill, and the checkmark on the other filled-in fields.'=>'Kłódka przy nazwie firmy i numerze identyfikacyjnym firmy po autouzupełnieniu oraz znacznik wyboru przy pozostałych uzupełnionych polach.','Verified'=>'Zweryfikowane','Padlock and checkmark. Leave empty for green (#007518).'=>'Kłódka i znacznik wyboru. Pozostaw puste, aby użyć koloru zielonego (#007518).','Clear'=>'Wyczyszczone','The X the padlock turns into. Leave empty for red (#a00).'=>'Krzyżyk, w który zmienia się kłódka. Pozostaw puste, aby użyć koloru czerwonego (#a00).','Company name suggestions'=>'Podpowiedzi nazw firm','By default the list takes its colours from the company field.'=>'Domyślnie lista przejmuje kolory z pola nazwy firmy.','Background'=>'Tło','Text'=>'Tekst','Border'=>'Obramowanie','Highlighted suggestion'=>'Wyróżniona podpowiedź','Leave empty for a tint of the text colour.'=>'Pozostaw puste, aby użyć odcienia koloru tekstu.','Corner radius'=>'Zaokrąglenie narożników','In pixels. Leave empty for the company field\'s own.'=>'W pikselach. Pozostaw puste, aby użyć zaokrąglenia pola nazwy firmy.','Finančná správa lists'=>'Listy Finančná správa','The DIČ and IČ DPH lists the Slovak checks run against, imported daily.'=>'Listy DIČ i IČ DPH, na podstawie których weryfikowane są słowackie numery, importowane codziennie.','%1$s (%2$s ago)'=>'%1$s (%2$s temu)','Off. Enable "SK: Validate in Finančná správa" in %s.'=>'Wyłączone. Włącz „SK: Weryfikuj w Finančná správa” w sekcji %s.','Validation'=>'Weryfikacja','Up to date'=>'Aktualne','Older than a week: Slovak numbers are checked in VIES only, or let through when "ignore when the check fails" is on.'=>'Starsze niż tydzień: słowackie numery są sprawdzane tylko w VIES albo akceptowane bez weryfikacji, gdy włączona jest opcja „Ignoruj nieudaną weryfikację”.','Not imported yet'=>'Jeszcze nie zaimportowano','Status'=>'Stan','Last import'=>'Ostatni import','%1$s DIČ, %2$s IČ DPH'=>'%1$s DIČ, %2$s IČ DPH','Database'=>'Baza danych','The file is missing, the next import creates it again.'=>'Brak pliku, następny import utworzy go ponownie.','Last failed import'=>'Ostatni nieudany import','Not scheduled, it is scheduled again on the next page load.'=>'Nie zaplanowano. Import zostanie zaplanowany przy następnym wczytaniu strony.','%s, overdue: WP-Cron has not run since. It runs on page visits, or set up a server cron job for wp-cron.php.'=>'%s, zaległy: WP-Cron od tego czasu nie działał. Uruchamia się przy odwiedzinach witryny; możesz też ustawić na serwerze zadanie cron dla wp-cron.php.','Next import'=>'Następny import','PHP extensions'=>'Rozszerzenia PHP','Import now'=>'Importuj teraz','Every import is logged in %s.'=>'Każdy import jest zapisywany w %s.','WooCommerce → Status → Logs'=>'WooCommerce → Status → Dziennik zdarzeń','Set by the %s filter in the theme or a plugin.'=>'Ustawione przez filtr %s w motywie lub wtyczce.','IČO DIČ'=>'IČO DIČ','Appearance'=>'Wygląd','Finančná správa'=>'Finančná správa','Enter a valid Business ID'=>'Wpisz prawidłowy numer identyfikacyjny firmy','%1$s is not corresponding to %2$s.'=>'%1$s nie zgadza się z danymi w rejestrze %2$s.' . "\0" . '%1$s nie zgadzają się z danymi w rejestrze %2$s.' . "\0" . '%1$s nie zgadzają się z danymi w rejestrze %2$s.','%s is not corresponding to Finančná správa.'=>'%s nie zgadza się z danymi z Finančná správa.' . "\0" . '%s nie zgadzają się z danymi z Finančná správa.' . "\0" . '%s nie zgadzają się z danymi z Finančná správa.','%s is not corresponding to ARES.'=>'%s nie zgadza się z danymi w ARES.' . "\0" . '%s nie zgadzają się z danymi w ARES.' . "\0" . '%s nie zgadzają się z danymi w ARES.','field labelThe billing country does not correspond to the country of the %s.'=>'Kraj rozliczeniowy nie zgadza się z krajem numeru w polu %s.','field labelThe shipping country does not correspond to the country of the %s.'=>'Kraj wysyłki nie zgadza się z krajem numeru w polu %s.','field label%s has not a correct format.'=>'Pole %s ma nieprawidłowy format.','field labelEnter a valid %s.'=>'Wpisz prawidłową wartość w polu %s.','field labelCould not validate %s.'=>'Nie udało się zweryfikować pola %s.','%1$s or %2$s is not valid.'=>'Pole %1$s lub %2$s jest nieprawidłowe.','Tax ID does not belong to the entered Business ID.'=>'NIP nie odpowiada podanemu numerowi identyfikacyjnemu firmy.','Could not validate Tax ID.'=>'Nie udało się zweryfikować numeru NIP.']];